namespace sv_272cc05d7f924e38874b041069113858.Services;

/// <summary>
/// Scoped service (per-circuit) that tracks low-stock alert counts.
/// Components subscribe to OnChange to be notified when new data arrives.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }
    public string? CurrentWarehouseId { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches new alert data and notifies all subscribers.
    /// Called by the polling component; all other subscribers react automatically.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentWarehouseId = warehouseId;
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

