using Microsoft.AspNetCore.Components;
using sv_272cc05d7f924e38874b041069113858.Components;
using sv_272cc05d7f924e38874b041069113858.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Warehouse selection cascaded app-wide via DI (crosses render-mode boundaries).
builder.Services.AddCascadingValue(sp =>
{
    var initial = WarehouseInfo.AvailableWarehouses[0];
    return new CascadingValueSource<WarehouseInfo>(initial, isFixed: false);
});

// Scoped = per-circuit = per-user isolation on Blazor Server.
builder.Services.AddScoped<InventoryAlertService>();

arguments.file_text:
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource

<select class="form-select form-select-sm"
        style="width: 200px;"
        value="@_selectedId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.AvailableWarehouses)
    {
        <option value="@wh.WarehouseId">@wh.WarehouseName</option>
    }
</select>

@code {
    private string _selectedId = WarehouseInfo.AvailableWarehouses[0].WarehouseId;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? _selectedId;
        var selected = WarehouseInfo.AvailableWarehouses
            .First(w => w.WarehouseId == _selectedId);
        await WarehouseSource.NotifyChangedAsync(selected);
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because RefreshAsync fires OnChange from a timer thread.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

